// Descobre o nome interno de cada coluna na lista e monta a consulta paginada.
const cfg = $('Configuração').first().json;
const campos = $input.first().json.value || [];

// Coluna na planilha -> nomes de exibição possíveis na lista (sem diferenciar acento/maiúscula/espaço)
const COLUNAS = {
  'ID':                   ['ID'],
  'Criado':               ['Criado', 'Created'],
  'Status':               ['Status'],
  'Classificação':        ['Classificação'],
  'Finalidade':           ['Finalidade'],
  'Title':                ['Title', 'Título'],
  'Descrição':            ['Descrição'],
  'Solicitante':          ['Solicitante'],
  'Valor':                ['Valor', 'Valor Deposito', 'Valor Depósito'],
  'Placa Cavalo/Carreta': ['Placa Cavalo/Carreta'],
  'Gestor':               ['Gestor'],
  'Ordem de Serviço':     ['Ordem de Serviço'],
  'Modificado':           ['Modificado', 'Modified'],
  'Empresa':              ['Empresa'],
};
const FIXOS = { 'ID': 'ID', 'Criado': 'Created', 'Modificado': 'Modified', 'Title': 'Title' };

const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();
const mapa = {};
const faltando = [];
for (const [coluna, nomes] of Object.entries(COLUNAS)) {
  if (FIXOS[coluna]) {
    const f = campos.find(c => c.InternalName === FIXOS[coluna]);
    mapa[coluna] = { interno: FIXOS[coluna], tipo: f ? f.TypeAsString : '' };
    continue;
  }
  const alvo = nomes.map(norm);
  const f = campos.find(c => alvo.includes(norm(c.Title)) || alvo.includes(norm(c.InternalName)));
  if (f) mapa[coluna] = { interno: f.InternalName, tipo: f.TypeAsString };
  else faltando.push(coluna);
}
if (faltando.length) {
  throw new Error('Colunas não encontradas na lista: ' + faltando.join(', ') +
    '. Colunas disponíveis: ' + campos.map(c => c.Title).join(' | '));
}

const viewFields = Object.values(mapa).map(m => `<FieldRef Name="${m.interno}"/>`).join('');
const viewXml = '<View Scope="RecursiveAll">' +
  '<Query><OrderBy><FieldRef Name="ID" Ascending="TRUE"/></OrderBy></Query>' +
  `<ViewFields>${viewFields}</ViewFields>` +
  `<RowLimit Paged="TRUE">${cfg.linhasPorPagina}</RowLimit></View>`;

return [{ json: {
  endpoint: `${cfg.siteUrl}/_api/web/lists(guid'${cfg.listId}')/RenderListDataAsStream`,
  corpo: { parameters: { RenderOptions: 2, ViewXml: viewXml, DatesInUtc: true } },
  mapa,
} }];

// Junta todas as páginas e converte para as mesmas colunas/formatos da exportação do Excel.
const cfg = $('Configuração').first().json;
const { mapa } = $('Montar consulta').first().json;
const linhas = $input.all().flatMap(i => i.json.Row || []);

// Trava de segurança: não sobrescreve a base boa com uma leitura incompleta
if (linhas.length < Number(cfg.minimoLinhas)) {
  throw new Error(`Leitura incompleta: ${linhas.length} linhas (mínimo ${cfg.minimoLinhas}). Arquivo NÃO atualizado.`);
}

const entidades = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&nbsp;': ' ' };
const limparTexto = s => String(s)
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div)>/gi, '\n').replace(/<[^>]+>/g, '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&[a-z#0-9]+;/gi, e => entidades[e] ?? e)
  .replace(/​/g, '').replace(/\n{2,}/g, '\n').trim();

const texto = v => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(texto).filter(Boolean).join('; ');
  if (typeof v === 'object') return texto(v.title ?? v.lookupValue ?? v.Label ?? v.value ?? '');
  return limparTexto(v);
};

const numero = (r, interno) => {
  const bruto = r[interno + '.'];                    // valor sem formatação, ex.: "360.000000000000"
  if (bruto !== undefined && bruto !== '') return Number(bruto);
  const v = r[interno];
  if (v === undefined || v === null || v === '') return null;
  return Number(String(v).replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.'));
};

const dataHora = (r, interno) => {
  const v = r[interno + '.'] || r[interno];
  if (!v) return '';
  let d = DateTime.fromISO(String(v), { zone: 'utc' });
  if (!d.isValid) d = DateTime.fromFormat(String(v), 'dd/MM/yyyy HH:mm', { zone: 'utc' });
  if (!d.isValid) return String(v);
  return d.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd HH:mm:ss');
};

const TIPOS_NUMERO = ['Number', 'Currency', 'Counter', 'Integer'];
const TIPOS_DATA = ['DateTime'];

return linhas.map(r => {
  const saida = {};
  for (const [coluna, { interno, tipo }] of Object.entries(mapa)) {
    if (TIPOS_NUMERO.includes(tipo) || coluna === 'ID' || coluna === 'Valor') saida[coluna] = numero(r, interno);
    else if (TIPOS_DATA.includes(tipo) || coluna === 'Criado' || coluna === 'Modificado') saida[coluna] = dataHora(r, interno);
    else saida[coluna] = texto(r[interno]);
  }
  return { json: saida };
});
